    f.write(f'''def transform(grid):
    if not grid:
        return grid
    h, w = len(grid), len(grid[0])
    # Find the background color (most frequent)
    counts = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Find unique-colored cells and shift them down by 1
    result = [[background]*w for _ in range(h)]
    for r in range(h-1):  # don't process last row (no room to shift down)
        for c in range(w):
            if grid[r][c] != background:
                result[r+1][c] = grid[r][c]
    return result
''')

